#         (월수 ≥ SELAUDIT_COVER_VERDICT_MIN_MONTHS 60 · t ≥ 2.5 · 구간 앞·뒤 절반 IC > 0 · 연도 ≥ 60% · 같은 달 무작위 순위 대조군 95백분위).
