#         빠졌던 것을 막는다. 묶음 다운로드 예외 재시도 SELAUDIT_CHUNK_RETRY(1). 00S 'A. 티커 변경 복구' 줄 · 'B2. 확보율 ≥90% 달만'(참고 교차표 ·
