#        합집합 ≈ 1 − 0.67×0.67×0.85 ≈ **0.6** → **60%의 날을 잘라낸다.**
#      합성 데이터 실측: 평균노출 **0.4942**, 즉 대체하려던 ext200(**0.5866**)보다 **더 낮다.**
