#        아니다.** 분위 버킷은 위험 이벤트가 아니라 **상태 배분기**이므로 라이브 감축 규칙이 될 수
#        없다. 라이브 감축 규칙은 **이벤트 모양**(시작과 끝이 있는 짧은 구간)이어야 한다.
