DIP_DD_THRESHOLD: float = -0.10       # 21일 고점 대비 하락 이벤트 문턱
DIP_HOLD_DAYS: int = 21               # 이벤트 뒤 상태 유지 거래일
DIP_EARN_WINDOW: int = 4              # 어닝 발표 뒤 며칠 안의 하락이면 '어닝 하락'
